import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Bring your own key · 换成自己的 key","description":"","frontmatter":{},"headers":[],"relativePath":"own-key.md","filePath":"own-key.md"}'),d={name:"own-key.md"};function i(r,e,s,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="bring-your-own-key-·-换成自己的-key" tabindex="-1">Bring your own key · 换成自己的 key <a class="header-anchor" href="#bring-your-own-key-·-换成自己的-key" aria-label="Permalink to &quot;Bring your own key · 换成自己的 key&quot;">​</a></h1><p><a href="#中文">中文</a> · <a href="#english">English</a></p><p>nanoMuse is free and non-profit. The model behind it costs money, and the developer pays for a starting allowance — ¥10 per account at the time of writing, plus ¥5 for you and ¥5 for them each time a friend signs up with your code (the app shows the relay&#39;s current figures). When it is gone, the quickest way on is a key of your own.</p><p>Which provider depends on where you are:</p><table tabindex="0"><thead><tr><th></th><th>Provider</th><th>Chat model</th><th>Hands model</th><th>Base URL</th></tr></thead><tbody><tr><td>Mainland China</td><td><strong>Alibaba Cloud Bailian (阿里云百炼)</strong></td><td><code>deepseek-v4.1-flash</code></td><td><code>qwen3.8-27b</code></td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td></tr><tr><td>Everywhere else</td><td><strong>OpenRouter</strong></td><td><code>deepseek/deepseek-v4.1-flash</code></td><td><code>qwen/qwen3.8-27b</code></td><td><code>https://openrouter.ai/api/v1</code></td></tr></tbody></table><p>Bailian only signs up accounts with a mainland Chinese identity, and its international edition (dashscope-intl) does not carry these two models. Outside mainland China, OpenRouter is the easy way: one account, one key, international cards, pay as you go. The other provider stays as a second option on every client, and any OpenAI-compatible endpoint works too.</p><p>Your sign-in, your invite code and your devices are not affected: the account stays, only the model provider changes. Nothing you say passes through nanoMuse Cloud once your own key is in use.</p><hr><h2 id="中文" tabindex="-1">中文 <a class="header-anchor" href="#中文" aria-label="Permalink to &quot;中文&quot;">​</a></h2><h3 id="先看你在哪" tabindex="-1">先看你在哪 <a class="header-anchor" href="#先看你在哪" aria-label="Permalink to &quot;先看你在哪&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>服务商</th><th>对话模型</th><th>手的模型</th><th>地址</th></tr></thead><tbody><tr><td>中国大陆</td><td><strong>阿里云百炼</strong></td><td><code>deepseek-v4.1-flash</code></td><td><code>qwen3.8-27b</code></td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td></tr><tr><td>海外</td><td><strong>OpenRouter</strong></td><td><code>deepseek/deepseek-v4.1-flash</code></td><td><code>qwen/qwen3.8-27b</code></td><td><code>https://openrouter.ai/api/v1</code></td></tr></tbody></table><p>百炼只给中国大陆身份注册，国际版（dashscope-intl）也没有这两个模型。海外用户用不了百炼，推荐 OpenRouter：一个账号一把 key，国际信用卡，按量付费。两家在每个客户端里都是预设，另一家始终是第二选择。</p><p>对话模型和手的模型是两个设置：对话模型在模型选择里，手的模型在「手的模型」一行（手机：设置 → Hands；网页版 / 桌面版：连接）。额度没用完时它们默认分别是 <code>deepseek-v4.1-flash</code> 和 <code>qwen3.8-27b</code>，换成自己的 key 之后也照这两个选。</p><h3 id="阿里云百炼-中国大陆" tabindex="-1">阿里云百炼（中国大陆） <a class="header-anchor" href="#阿里云百炼-中国大陆" aria-label="Permalink to &quot;阿里云百炼（中国大陆）&quot;">​</a></h3><ul><li>新账号有一段时间的免费 token；对话、画图（qwen-image）、视频（Wan）都在同一把 key 下，形象生成也能直接用。</li><li>国内直连，接口 OpenAI 兼容，nanoMuse 里已经预置好地址，只要贴 key。</li><li>注册需要阿里云账号和实名认证，海外身份注册不了。</li></ul><p><strong>五步，约 2 分钟：</strong></p><ol><li><strong>开通百炼。</strong> 打开 <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a>，用阿里云账号登录（没有就注册一个，要实名认证）。第一次进入会提示「开通百炼服务」，点开通，不收费。</li><li><strong>创建 API key。</strong> 进入 <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY 管理页</a>（右上角头像 → API-KEY），点「创建我的 API-KEY」，归属选默认业务空间，确定。</li><li><strong>复制 key。</strong> 新建的 key 以 <code>sk-</code> 开头。点「查看」再「复制」。<strong>这串字符只给 nanoMuse 用，不要发给任何人、不要贴到聊天里。</strong></li><li><strong>贴到 nanoMuse 里。</strong><ul><li>手机：额度用完时卡片上的「去设置」会打开预填好的「阿里云百炼」表单；或者 设置 → 服务商 → 添加 → OpenAI 类型，地址填 <code>https://dashscope.aliyuncs.com/compatible-mode</code>（勾上 <code>/v1</code>）。贴 key，保存。</li><li>网页版 / 桌面版：额度卡片上的「去设置」会打开「连接」页并选好「阿里云百炼」；或者 连接 → 模型 → 「阿里云百炼」。贴 key，保存。</li></ul></li><li><strong>选模型，试一句。</strong> 保存后 nanoMuse 列出这把 key 能用的模型：对话选 <code>deepseek-v4.1-flash</code>（能看图，便宜），手的模型选 <code>qwen3.8-27b</code>；想更省，对话也可以选 <code>qwen3.8-flash</code>。回到聊天说一句，能回答就成了。想换形象，再到 连接 → 图像与视频模型 里选 <code>qwen-image-3.0</code> 和 <code>wan2.2-i2v-flash</code>。</li></ol><p><strong>之后怎么算钱。</strong> 免费额度用完后按百炼标价计费（北京地域）：<code>deepseek-v4.1-flash</code> 每百万 token 输入 ¥2 / 输出 ¥8（忙时；闲时 ¥1 / ¥4），<code>qwen3.8-27b</code> ¥3 / ¥12，<code>qwen3.8-flash</code> ¥0.8 / ¥2.7，<code>qwen-image-3.0</code> 每张 ¥0.18，<code>wan2.2-i2v-flash</code> 每秒 ¥0.10。正常聊一天几分钱。建议在百炼控制台设一个<strong>用量告警</strong>。nanoMuse 自己不收任何费用。</p><h3 id="openrouter-海外" tabindex="-1">OpenRouter（海外） <a class="header-anchor" href="#openrouter-海外" aria-label="Permalink to &quot;OpenRouter（海外）&quot;">​</a></h3><ul><li>一个账号、一把 key，几百个模型都在后面；国际信用卡付费，按量扣。</li><li>不用代理，不用国内身份。</li><li>手机 App（Android、iPhone）可以一键登录 OpenRouter，不用手抄 key。</li></ul><p><strong>四步：</strong></p><ol><li><strong>注册。</strong> 打开 <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a>，用 Google、GitHub 或邮箱登录。</li><li><strong>充值。</strong> 右上角头像 → <em>Credits</em> → <em>Add Credits</em>，国际信用卡；先充 5 美元足够用很久。</li><li><strong>拿 key。</strong> 头像 → <em>Keys</em> → <em>Create Key</em>，起个名（比如 nanoMuse），复制以 <code>sk-or-v1-</code> 开头的那串。<strong>只给 nanoMuse 用，别发给任何人。</strong></li><li><strong>贴到 nanoMuse 里。</strong><ul><li>手机：设置 → 服务商 → 添加 → OpenRouter → 「登录」，浏览器里批准一下，key 自动回到 App，不用复制；或者把 key 贴进 OpenRouter 表单。</li><li>网页版 / 桌面版：连接 → 模型 → 「OpenRouter」，贴 key，保存。地址已经填好：<code>https://openrouter.ai/api/v1</code>。</li></ul></li></ol><p><strong>选模型。</strong> 对话选 <code>deepseek/deepseek-v4.1-flash</code>，手的模型选 <code>qwen/qwen3.8-27b</code>。每个模型的单价在 OpenRouter 的模型页上写着；<em>Settings → Limits</em> 可以给 key 设每月上限。</p><h3 id="deepseek-官方接口" tabindex="-1">DeepSeek 官方接口 <a class="header-anchor" href="#deepseek-官方接口" aria-label="Permalink to &quot;DeepSeek 官方接口&quot;">​</a></h3><p>只想要 DeepSeek 的话，可以直接用它家的接口：<a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a> 注册、充值、创建 key，地址 <code>https://api.deepseek.com/v1</code>，模型选 <code>deepseek-v4.1-flash</code>。它没有图像和视频模型，形象生成要另配一家。</p><h3 id="其他-openai-兼容服务商" tabindex="-1">其他 OpenAI 兼容服务商 <a class="header-anchor" href="#其他-openai-兼容服务商" aria-label="Permalink to &quot;其他 OpenAI 兼容服务商&quot;">​</a></h3><p>任何 OpenAI 兼容接口都能填：智谱、月之暗面、OpenAI 本身，或你自己跑的 vLLM / Ollama。通用填法：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>类型</td><td>OpenAI（兼容）</td></tr><tr><td>地址（Base URL）</td><td>服务商给的地址，通常以 <code>/v1</code> 结尾，例如 <code>https://api.deepseek.com/v1</code></td></tr><tr><td>API key</td><td>服务商控制台里创建的 key</td></tr><tr><td>模型</td><td>保存后从列表里选；列不出来就手填服务商文档里的模型 id</td></tr></tbody></table><p>网页版和桌面版的「连接」页里有常见服务商的预设，选中即填好地址，只差 key。手的模型要能看图：DeepSeek 的模型里只有 id 带 <code>v4.1</code>（或更新）、<code>vision</code>、<code>ocr</code> 的才看得见截图。</p><hr><h2 id="english" tabindex="-1">English <a class="header-anchor" href="#english" aria-label="Permalink to &quot;English&quot;">​</a></h2><h3 id="where-you-are-decides-the-provider" tabindex="-1">Where you are decides the provider <a class="header-anchor" href="#where-you-are-decides-the-provider" aria-label="Permalink to &quot;Where you are decides the provider&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Provider</th><th>Chat model</th><th>Hands model</th><th>Base URL</th></tr></thead><tbody><tr><td>Mainland China</td><td><strong>Alibaba Cloud Bailian (阿里云百炼)</strong></td><td><code>deepseek-v4.1-flash</code></td><td><code>qwen3.8-27b</code></td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td></tr><tr><td>Everywhere else</td><td><strong>OpenRouter</strong></td><td><code>deepseek/deepseek-v4.1-flash</code></td><td><code>qwen/qwen3.8-27b</code></td><td><code>https://openrouter.ai/api/v1</code></td></tr></tbody></table><p>Alibaba Cloud Bailian only signs up accounts from mainland China, and its international edition (dashscope-intl) does not carry these two models. Outside, OpenRouter is the easy way: one account, one key, pay as you go. Both are presets on every client; the other one stays as the second option.</p><p>The chat model and the hands model are two settings: the chat model in the model picker, the hands model on the <em>Hands model</em> row (phone: <em>Settings → Hands</em>; web and desktop: <em>Connections</em>). On the free allowance they default to <code>deepseek-v4.1-flash</code> and <code>qwen3.8-27b</code>; pick the same two under your own key.</p><h3 id="alibaba-cloud-bailian-mainland-china" tabindex="-1">Alibaba Cloud Bailian (mainland China) <a class="header-anchor" href="#alibaba-cloud-bailian-mainland-china" aria-label="Permalink to &quot;Alibaba Cloud Bailian (mainland China)&quot;">​</a></h3><ul><li>A new account comes with free tokens for a while; chat, pictures (qwen-image) and video (Wan) sit under one key, so the avatar studio works too.</li><li>Direct from China, OpenAI-compatible; nanoMuse already knows the endpoint, you only paste the key.</li><li>Sign-up needs an Alibaba Cloud account with mainland identity verification; it does not accept overseas accounts.</li></ul><p><strong>Five steps, about two minutes:</strong></p><ol><li><strong>Open Bailian.</strong> Go to <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a> and sign in with an Alibaba Cloud account (create one if needed; identity verification is required). On first entry accept <em>Enable Model Studio</em> — it is free.</li><li><strong>Create an API key.</strong> Open the <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY page</a> (avatar, top right → API-KEY), click <em>Create my API-KEY</em>, keep the default workspace, confirm.</li><li><strong>Copy it.</strong> The key starts with <code>sk-</code>. Click <em>View</em>, then <em>Copy</em>. <strong>It is for nanoMuse only — never send it to anyone or paste it into a chat.</strong></li><li><strong>Paste it into nanoMuse.</strong><ul><li>Phone: <em>Set it up</em> on the allowance card opens the provider form pre-filled for Bailian; or <em>Settings → Providers → Add → OpenAI</em>, base URL <code>https://dashscope.aliyuncs.com/compatible-mode</code> with <code>/v1</code> on. Paste the key, save.</li><li>Web / desktop: <em>Set it up</em> on the allowance card opens <em>Connections</em> with <em>Alibaba Cloud Bailian</em> chosen; or <em>Connections → Model → Alibaba Cloud Bailian</em>. Paste the key, save.</li></ul></li><li><strong>Pick the models, say something.</strong> After saving, nanoMuse lists the models the key can use: <code>deepseek-v4.1-flash</code> for chat (sees images, cheap), <code>qwen3.8-27b</code> as the hands model; <code>qwen3.8-flash</code> is the cheaper chat option. Back in the chat, one sentence answered means it works. For the avatar, choose <code>qwen-image-3.0</code> and <code>wan2.2-i2v-flash</code> under <em>Connections → Image &amp; video models</em>.</li></ol><p><strong>What it costs afterwards.</strong> Past the free quota, Bailian bills at list price (Beijing region): <code>deepseek-v4.1-flash</code> ¥2 in / ¥8 out per million tokens in busy hours (¥1 / ¥4 off-peak), <code>qwen3.8-27b</code> ¥3 / ¥12, <code>qwen3.8-flash</code> ¥0.8 / ¥2.7, <code>qwen-image-3.0</code> ¥0.18 a picture, <code>wan2.2-i2v-flash</code> ¥0.10 a second. An ordinary day of chatting is a few fen. Set a <strong>usage alert</strong> in the Bailian console. nanoMuse itself charges nothing.</p><h3 id="openrouter-everywhere-else" tabindex="-1">OpenRouter (everywhere else) <a class="header-anchor" href="#openrouter-everywhere-else" aria-label="Permalink to &quot;OpenRouter (everywhere else)&quot;">​</a></h3><ul><li>One account and one key in front of hundreds of models; international cards; pay as you go.</li><li>No proxy, no mainland identity.</li><li>The phone apps (Android, iPhone) sign in to OpenRouter with one tap — no key to copy.</li></ul><p><strong>Four steps:</strong></p><ol><li><strong>Sign up.</strong> Go to <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a> and sign in with Google, GitHub or an e-mail address.</li><li><strong>Add credit.</strong> Avatar, top right → <em>Credits</em> → <em>Add Credits</em>, with an international card; $5 lasts a long time.</li><li><strong>Make a key.</strong> Avatar → <em>Keys</em> → <em>Create Key</em>, give it a name (nanoMuse, say), copy the string starting <code>sk-or-v1-</code>. <strong>For nanoMuse only; never send it to anyone.</strong></li><li><strong>Paste it into nanoMuse.</strong><ul><li>Phone: <em>Settings → Providers → Add → OpenRouter → Sign in</em> — the browser opens OpenRouter, you approve, and the key comes back to the app on its own; or paste the key into the OpenRouter form.</li><li>Web / desktop: <em>Connections → Model → OpenRouter</em>, paste the key, save. The address is already filled in: <code>https://openrouter.ai/api/v1</code>.</li></ul></li></ol><p><strong>Pick the models.</strong> <code>deepseek/deepseek-v4.1-flash</code> for chat, <code>qwen/qwen3.8-27b</code> as the hands model. Each model&#39;s price is on its OpenRouter page; <em>Settings → Limits</em> puts a monthly cap on a key.</p><h3 id="deepseek-direct" tabindex="-1">DeepSeek direct <a class="header-anchor" href="#deepseek-direct" aria-label="Permalink to &quot;DeepSeek direct&quot;">​</a></h3><p>If DeepSeek is all you want, its own endpoint works: sign up, add credit and create a key at <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a>, base URL <code>https://api.deepseek.com/v1</code>, model <code>deepseek-v4.1-flash</code>. DeepSeek has no image or video models, so the avatar studio needs a second provider.</p><h3 id="any-other-openai-compatible-provider" tabindex="-1">Any other OpenAI-compatible provider <a class="header-anchor" href="#any-other-openai-compatible-provider" aria-label="Permalink to &quot;Any other OpenAI-compatible provider&quot;">​</a></h3><p>Anything that speaks the OpenAI API works: Zhipu, Moonshot, OpenAI itself, or your own vLLM / Ollama. The generic fill-in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Type</td><td>OpenAI (compatible)</td></tr><tr><td>Base URL</td><td>the provider&#39;s address, usually ending in <code>/v1</code>, e.g. <code>https://api.deepseek.com/v1</code></td></tr><tr><td>API key</td><td>the key made in the provider&#39;s console</td></tr><tr><td>Model</td><td>pick from the list after saving; if none appears, type the model id from the provider&#39;s docs</td></tr></tbody></table><p>The web and desktop <em>Connections</em> page has presets for the common providers: choose one and the address is filled in — only the key is missing. The hands model has to see pictures: of DeepSeek&#39;s models, only ids containing <code>v4.1</code> (or later), <code>vision</code> or <code>ocr</code> can read a screenshot.</p>',51)])])}const m=o(d,[["render",i]]);export{u as __pageData,m as default};
